def prod_signs(arr):
    if not arr:
        return None

    total_magnitude = sum(abs(x) for x in arr)
    sign_product = 1
    for x in arr:
        if x > 0:
            sign_product *= 1
        elif x < 0:
            sign_product *= -1
        else:
            sign_product *= 0

    return total_magnitude * sign_product
